begin;
set local lock_timeout='5s';
lock table questions,question_keys,revision_items,audit_log in share row exclusive mode;
create temporary table release_candidates on commit drop as select * from jsonb_to_recordset('[{"id":"30b154fb-685f-5899-8c46-390928fb405c","track":"est2","lesson":"Statistics and data analysis","idea":"First whole date above a linear regression threshold","difficulty":"medium","programmes":["est2"],"focus":{"takeaway":"Fit the line, solve the threshold inequality, then map the first integer input to its date.","collections":["unique"],"math_format":"plain","source_label":"EST II - Math Level 1 - December 2020.pdf","source_reference":"EST2-L1-DEC2020-Q45","bank_occurrences":1},"qhash":"2d4db31abcc9d3ec34ff595172a2d7bf","khash":"2ad2eb0fbc4a5728337a60f95367b1f6","rhash":null,"restore":false},{"id":"6b2fb270-3b63-5e81-8abd-dd6a4e237a16","track":"est2","lesson":"Functions and transformations","idea":"Recognizing an ellipse from trigonometric parametrization","difficulty":"medium","programmes":["est2"],"focus":{"takeaway":"Divide by each positive semiaxis, square, and add using sin²t+cos²t=1.","collections":["unique"],"math_format":"plain","source_label":"EST II - Math Level 1 - May 2021.pdf","source_reference":"EST2-L1-MAY2021-Q11","bank_occurrences":1},"qhash":"1b21f8dd060ebea2f8c858ec912c9f6b","khash":"4a0ea124f0f2b21613d96c711f5b3791","rhash":null,"restore":false},{"id":"756766cb-80b1-5643-91a9-dee54bc64f4b","track":"est","lesson":"Statistics and data analysis","idea":"Reading right skew from a box plot","difficulty":"medium","programmes":["est"],"focus":{"takeaway":"Compare the two box halves and whiskers to identify a longer right tail.","collections":["must_know","unique"],"math_format":"plain","source_label":"EST_I_Math_Questions_by_Topic-2.pdf","source_reference":"DAP 073","bank_occurrences":1},"qhash":"a392c60ab7eed5ecb2a45f28957278f0","khash":"eb00fc0097534a2db2f9a7104da097f1","rhash":null,"restore":false},{"id":"845c7e7a-5832-5e39-a9b0-96de90b215af","track":"est2","lesson":"Functions and transformations","idea":"Recovering ellipse semiaxes from area and their sum","difficulty":"medium","programmes":["est2"],"focus":{"takeaway":"Use area=πab and a+b to solve for ordered positive semiaxes.","collections":["unique"],"math_format":"plain","source_label":"EST II - Math Level 1 - October 2021.pdf","source_reference":"EST2-L1-OCT2021-Q38","bank_occurrences":1},"qhash":"9c69f57f8b1ad191231055d61511610a","khash":"572db41a1649f15378244f095b7067ff","rhash":null,"restore":false},{"id":"a064109e-b94e-5cd6-b13d-ceeca6c47d75","track":"est2","lesson":"Trigonometry","idea":"Trigonometric identities","difficulty":"medium","programmes":["est2"],"focus":{"takeaway":"Key skill: Trigonometric identities.","collections":["must_know","repeated"],"math_format":"plain","bank_occurrences":8},"qhash":"6d0d47d4ea8259a229977050886b64cb","khash":"421c278fc9abd76b8b20d05dc3658081","rhash":"ab40d3d775be25785fe6aba7ec4a6bcd","restore":true},{"id":"cc64f92a-b880-5425-bcfd-0958bd67eecb","track":"est2","lesson":"Functions and transformations","idea":"Inverse functions","difficulty":"easy","programmes":["est2"],"focus":{"takeaway":"Key skill: Inverse functions.","collections":["must_know","repeated"],"math_format":"plain","bank_occurrences":4},"qhash":"7adc81515b1792f32ef9ad98dfc40546","khash":"918e90f0c2c76d2fdea6386e415cc3bf","rhash":"80a092b4bf6a0796750513a8f77426ca","restore":true},{"id":"de8a0823-e377-6714-88ee-47b1697cae15","track":"sat","lesson":"Statistics and data analysis","idea":"Finding the largest absolute residual","difficulty":"medium","programmes":["sat"],"focus":{"takeaway":"Compare observed minus fitted values; report the requested observed coordinate.","collections":["must_know","unique"],"math_format":"plain","source_label":"College Panda 10 Practice Tests, p19, test 1 section 4 Q38","source_reference":"Test 1, section 4, question 38","bank_occurrences":1},"qhash":"d3f4b7671a6c2355822e7b47495819a5","khash":"4314b4204c492c5aacb38f1755f1a4fa","rhash":null,"restore":false},{"id":"e8e32b3c-a067-5ae4-9f6d-74451f26ef3f","track":"est2","lesson":"Trigonometry","idea":"Trigonometric graphs and parameters","difficulty":"easy","programmes":["est2"],"focus":{"takeaway":"Key skill: Trigonometric graphs and parameters.","collections":["must_know","repeated"],"math_format":"plain","bank_occurrences":7},"qhash":"d68404997fea457609cabe10647cfc6f","khash":"39c0156451180e8954caf5b6549ddd11","rhash":"345d0122c7e2397fcb3ac7a9c9310916","restore":true},{"id":"eaded88c-e857-5fec-afe1-3b7a282813f6","track":"est2","lesson":"Trigonometry","idea":"Trigonometric identities","difficulty":"easy","programmes":["est2"],"focus":{"takeaway":"Key skill: Trigonometric identities.","collections":["must_know","repeated"],"math_format":"plain","bank_occurrences":8},"qhash":"67301f113e5900e28e50ac6bd7caf479","khash":"714ddb73259d64d5795ab590ed8b2083","rhash":"7bf145c40cf0ff4aa3540392d19d9829","restore":true}]'::jsonb) as x(id uuid,track text,lesson text,idea text,difficulty text,programmes text[],focus jsonb,qhash text,khash text,rhash text,restore boolean);
do $$ begin
if exists(select 1 from audit_log where action='revision.cross_bank_additions.20260930') then raise exception 'Release already applied';end if;
if (select count(*) from release_candidates)<>9 then raise exception 'Incomplete release';end if;
if exists(select 1 from release_candidates x left join questions q on q.id=x.id left join question_keys k on k.question_id=x.id left join revision_items r on r.question_id=x.id
where q.id is null or k.question_id is null or md5(to_jsonb(q)::text)<>x.qhash or md5(to_jsonb(k)::text)<>x.khash
or q.track_id<>x.track or q.topic<>x.lesson or nullif(q.assets->>'release_hold_reason','') is not null or coalesce((q.assets->>'bank_removed')::boolean,false)
or q.assets->>'source_code' like 'EST2-L2-%' or coalesce(q.assets->>'source_document','') ilike '%Math Level 2%'
or k.correct is null or coalesce((k.correct->>'void')::boolean,false) or nullif(k.explanation,'') is null
or (x.restore and (r.question_id is null or r.active or md5(to_jsonb(r)::text)<>x.rhash or r.fingerprint<>revision_question_fingerprint(q.stem,q.choices,q.assets,k.correct,k.explanation)))
or (not x.restore and r.question_id is not null)) then raise exception 'Source or revision version changed or ineligible';end if;
if exists(select 1 from release_candidates x join revision_items r on r.lesson=x.lesson and lower(trim(r.idea))=lower(trim(x.idea)) and r.difficulty=x.difficulty join questions q on q.id=r.question_id where r.active and q.track_id=x.track) then raise exception 'Idea difficulty already represented';end if;
if exists(select 1 from release_candidates x join questions q on q.id=x.id join questions d on d.track_id=q.track_id and d.id<>q.id and regexp_replace(lower(d.stem),'\s+',' ','g')=regexp_replace(lower(q.stem),'\s+',' ','g') and d.choices=q.choices join revision_items r on r.question_id=d.id where r.active) then raise exception 'Duplicate revision content';end if;
end $$;
update revision_items r set active=true from release_candidates x where x.restore and r.question_id=x.id;
insert into revision_items(question_id,lesson,idea,difficulty,programmes,fingerprint,active,focus)
select x.id,x.lesson,x.idea,x.difficulty,x.programmes,revision_question_fingerprint(q.stem,q.choices,q.assets,k.correct,k.explanation),true,x.focus from release_candidates x join questions q on q.id=x.id join question_keys k on k.question_id=q.id where not x.restore;
do $$ begin
if exists(select 1 from release_candidates x left join questions q on q.id=x.id left join question_keys k on k.question_id=x.id left join revision_items r on r.question_id=x.id
where r.question_id is null or not r.active or q.track_id<>x.track or r.lesson<>x.lesson or lower(trim(r.idea))<>lower(trim(x.idea)) or r.difficulty<>x.difficulty or r.programmes<>x.programmes or r.focus<>x.focus
or nullif(q.assets->>'release_hold_reason','') is not null or coalesce((q.assets->>'bank_removed')::boolean,false)
or r.fingerprint<>revision_question_fingerprint(q.stem,q.choices,q.assets,k.correct,k.explanation)) then raise exception 'Expected revision coverage missing or altered';end if;
if exists(select 1 from revision_items r join questions q on q.id=r.question_id where r.active group by q.track_id,r.lesson,lower(trim(r.idea)),r.difficulty having count(*)>2) then raise exception 'Representative cap exceeded';end if;
end $$;
insert into audit_log(action,target_type,target_id,meta)
select 'revision.cross_bank_additions.20260930','question',x.id::text,jsonb_build_object('track',x.track,'lesson',x.lesson,'idea',x.idea,'difficulty',x.difficulty,'restored',x.restore,'previous_revision',to_jsonb(r),'collections',x.focus->'collections','cap',2) from release_candidates x left join jsonb_to_recordset('[{"idea":"Trigonometric identities","focus":{"takeaway":"Key skill: Trigonometric identities.","collections":["must_know","repeated"],"math_format":"plain","bank_occurrences":8},"active":false,"lesson":"Trigonometry","difficulty":"medium","programmes":["est2"],"fingerprint":"52aec479acf48267552d1e20ed06c096","question_id":"a064109e-b94e-5cd6-b13d-ceeca6c47d75"},{"idea":"Inverse functions","focus":{"takeaway":"Key skill: Inverse functions.","collections":["must_know","repeated"],"math_format":"plain","bank_occurrences":4},"active":false,"lesson":"Functions and transformations","difficulty":"easy","programmes":["est2"],"fingerprint":"138a6ae3cda91d3aadcebdf1e9133972","question_id":"cc64f92a-b880-5425-bcfd-0958bd67eecb"},{"idea":"Trigonometric graphs and parameters","focus":{"takeaway":"Key skill: Trigonometric graphs and parameters.","collections":["must_know","repeated"],"math_format":"plain","bank_occurrences":7},"active":false,"lesson":"Trigonometry","difficulty":"easy","programmes":["est2"],"fingerprint":"b282543de27f0a53cf9495ff6d4ba03e","question_id":"e8e32b3c-a067-5ae4-9f6d-74451f26ef3f"},{"idea":"Trigonometric identities","focus":{"takeaway":"Key skill: Trigonometric identities.","collections":["must_know","repeated"],"math_format":"plain","bank_occurrences":8},"active":false,"lesson":"Trigonometry","difficulty":"easy","programmes":["est2"],"fingerprint":"fc5f5279d1fe78c376dd4cfc819038f8","question_id":"eaded88c-e857-5fec-afe1-3b7a282813f6"}]'::jsonb) as r(question_id uuid,lesson text,idea text,difficulty text,programmes text[],fingerprint text,active boolean,focus jsonb) on r.question_id=x.id;
commit;

